package ui;
import model.SessionUser; import service.AuthService; import javax.swing.*; import java.awt.*;
public class PasswordChangeDialog extends JDialog {
 public PasswordChangeDialog(JFrame owner, SessionUser user){super(owner,"Change password",true);setSize(390,270);setLocationRelativeTo(owner);JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createEmptyBorder(20,24,20,24));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JPasswordField old=new JPasswordField(),nw=new JPasswordField(),cf=new JPasswordField();for(JPasswordField x:new JPasswordField[]{old,nw,cf}){x.setFont(UITheme.REGULAR);x.setMaximumSize(new Dimension(Integer.MAX_VALUE,36));}p.add(UITheme.fieldLabel("Current password"));p.add(old);p.add(Box.createVerticalStrut(8));p.add(UITheme.fieldLabel("New password"));p.add(nw);p.add(Box.createVerticalStrut(8));p.add(UITheme.fieldLabel("Confirm new password"));p.add(cf);JButton save=UITheme.button("Save password",UITheme.TEAL);save.setAlignmentX(Component.LEFT_ALIGNMENT);save.addActionListener(e->{String a=new String(nw.getPassword()),b=new String(cf.getPassword());if(a.length()<8||!a.equals(b)){JOptionPane.showMessageDialog(this,"New passwords must match and contain at least 8 characters.");return;}try{new AuthService().changePassword(user.id,new String(old.getPassword()),a);JOptionPane.showMessageDialog(this,"Password changed successfully.");dispose();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Password change failed",JOptionPane.ERROR_MESSAGE);}});p.add(Box.createVerticalStrut(12));p.add(save);setContentPane(p);}
}
